 "content": "def transform(grid):
    """Repeat the interior pattern across each tile row, using its left marker color."""
    h, w = len(grid), len(grid[0])
    # Full-width/full-height solid lines are the tile separators.
    sep_rows = [r for r in range(h) if len(set(grid[r])) == 1 and grid[r][0] != 0]
    sep_cols = [c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1 and grid[0][c] != 0]
    row_edges = [-1] + sep_rows + [h]
    col_edges = [-1] + sep_cols + [w]
    bands = [(row_edges[i] + 1, row_edges[i + 1]) for i in range(len(row_edges) - 1)]
    tiles = [(col_edges[i] + 1, col_edges[i + 1]) for i in range(len(col_edges) - 1)]

    # The non-marker tile contains the pattern to be copied.
    pattern = None
    for r0, r1 in bands:
        for c0, c1 in tiles[1:]:
            points = [(r-r0, c-c0) for r in range(r0, r1) for c in range(c0, c1) if grid[r][c] != 0]
            if points:
                pattern = points
                break
        if pattern is not None:
            break
    if pattern is None:
        return [row[:] for row in grid]

    out = [row[:] for row in grid]
    for (r0, r1) in bands:
        c0, c1 = tiles[0]
        colors = [grid[r][c] for r in range(r0, r1) for c in range(c0, c1) if grid[r][c] != 0]
        if not colors:
            continue
        # Marker is the most frequent non-background color in the first tile.
        target = max(set(colors), key=colors.count)
        for t0, t1 in tiles:
            for r in range(r0, r1):
                for c in range(t0, t1):
                    out[r][c] = 0
            for dr, dc in pattern:
                if r0 + dr < r1 and t0 + dc < t1:
                    out[r0 + dr][t0 + dc] = target
    return out
